// Loads editable proof settings and the shared Insights Hub Config.
// In: manual trigger. Out: Graph settings and the lake base address.
var GRAPH_DRIVE_ID = 'PASTE_GRAPH_DRIVE_ID_HERE';
var GRAPH_FOLDER = 'PASTE_SHAREPOINT_FOLDER_PATH_HERE';
var GRAPH_FILE_NAME = 'PASTE_SMALL_FILE_NAME_HERE';
var GRAPH_TOKEN = 'PASTE_GRAPH_TOKEN_HERE';
var LAKE_FOLDER = 'sharepoint-proof';
var MAX_FILE_BYTES = 5242880;
var cfg = glob.get('cfg');

if (!cfg || cfg.platform !== 'xcelerator' || !cfg.xcTenantId) {
  msg.proofFailureReason = 'Run Config with xcelerator selected first';
  node.error(msg.proofFailureReason, msg);
  return null;
}

if (GRAPH_DRIVE_ID.indexOf('PASTE_') === 0 ||
  GRAPH_FOLDER.indexOf('PASTE_') === 0 ||
  GRAPH_FILE_NAME.indexOf('PASTE_') === 0 ||
  GRAPH_TOKEN.indexOf('PASTE_') === 0) {
  msg.proofFailureReason = 'Fill in the SharePoint proof settings';
  node.error(msg.proofFailureReason, msg);
  return null;
}

msg.proof = {
  driveId: GRAPH_DRIVE_ID,
  folder: GRAPH_FOLDER,
  fileName: GRAPH_FILE_NAME,
  graphToken: GRAPH_TOKEN,
  lakeFolder: LAKE_FOLDER,
  maxFileBytes: MAX_FILE_BYTES
};
msg.lakeBase = 'https://api.eu1.siemens.app/datalake-';
msg.lakeBase += cfg.xcTenantId + '/v3';
msg._proofStage = 'settings';
node.status({ fill: 'green', shape: 'dot', text: 'settings ready' });
return msg;

// Builds the Insights Hub client-credentials request.
// In: proof settings. Out: an HTTP request for the lake token.
var cfg = glob.get('cfg');

if (!cfg || !cfg.clientId || !cfg.clientSecret || !cfg.tokenUrl) {
  msg.proofFailureReason = 'Insights Hub credentials are missing in Config';
  node.error(msg.proofFailureReason, msg);
  return null;
}

msg.method = 'POST';
msg.url = cfg.tokenUrl;
msg.headers = {
  'Authorization': 'Basic ' + Buffer.from(
    cfg.clientId + ':' + cfg.clientSecret
  ).toString('base64'),
  'Accept': 'application/json'
};
if (cfg.tokenForm) {
  msg.headers['Content-Type'] = 'application/x-www-form-urlencoded';
  msg.payload = 'grant_type=client_credentials';
} else {
  delete msg.payload;
}
msg._proofStage = 'Insights Hub token';
node.status({ fill: 'blue', shape: 'dot', text: 'requesting lake token' });
return msg;

// Checks and retains the Insights Hub token for the proof.
// In: token HTTP response. Out: the same message with msg.lakeToken.
var token = msg.payload && msg.payload.access_token;

if (msg.statusCode !== 200 || !token) {
  msg.proofFailureReason = 'Insights Hub token HTTP ' + msg.statusCode;
  node.error(msg.proofFailureReason, msg);
  return null;
}

msg.lakeToken = token;
delete msg.payload;
msg._proofStage = 'lake token';
node.status({ fill: 'blue', shape: 'dot', text: 'lake token ready' });
return msg;

// Builds the SharePoint folder listing request.
// In: settings and lake token. Out: a Graph HTTP request.
var folder = String(msg.proof.folder || '');
var segments = folder.split('/').filter(function (part) {
  return part.length > 0;
}).map(function (part) {
  return encodeURIComponent(part);
}).join('/');
var path = '/root/children';

if (segments) {
  path = '/root:/' + segments + ':/children';
}

msg.method = 'GET';
msg.url = 'https://graph.microsoft.com/v1.0/drives/';
msg.url += encodeURIComponent(msg.proof.driveId) + path;
msg.url += '?$top=200&$select=id,name,size,lastModifiedDateTime,file';
msg.headers = {
  'Authorization': 'Bearer ' + msg.proof.graphToken,
  'Accept': 'application/json'
};
msg._proofStage = 'SharePoint listing';
node.status({ fill: 'blue', shape: 'dot', text: 'listing SharePoint folder' });
return msg;

// Selects the configured small file and builds its content request.
// In: Graph folder response. Out: a Graph download HTTP request.
if (msg.statusCode !== 200 || !msg.payload ||
  !Array.isArray(msg.payload.value)) {
  msg.proofFailureReason = 'SharePoint listing HTTP ' + msg.statusCode;
  node.error(msg.proofFailureReason, msg);
  return null;
}

var items = msg.payload.value;
var file = null;
for (var i = 0; i < items.length; i++) {
  var item = items[i];
  if (!item || !item.file || !item.name) {
    continue;
  }
  if (item.name.startsWith('~$')) {
    continue;
  }
  if (item.name === msg.proof.fileName) {
    file = item;
    break;
  }
}

if (!file) {
  msg.proofFailureReason = 'Configured file not found on the first page';
  node.error(msg.proofFailureReason, msg);
  return null;
}

var size = Number(file.size);
if (!Number.isFinite(size) || size > msg.proof.maxFileBytes) {
  msg.proofFailureReason = 'File size is invalid or exceeds 5 MiB';
  node.error(msg.proofFailureReason, msg);
  return null;
}

msg.proofFile = {
  id: file.id,
  name: file.name,
  size: size
};
msg.proofPartialList = Boolean(msg.payload['@odata.nextLink']);
msg.method = 'GET';
msg.url = 'https://graph.microsoft.com/v1.0/drives/';
msg.url += encodeURIComponent(msg.proof.driveId);
msg.url += '/items/' + encodeURIComponent(file.id) + '/content';
msg.headers = {
  'Authorization': 'Bearer ' + msg.proof.graphToken,
  'Accept': '*/*'
};
msg._proofStage = 'SharePoint download';
delete msg.payload;
node.status({
  fill: 'blue',
  shape: 'dot',
  text: 'downloading configured file'
});
return msg;

// Checks the downloaded bytes and requests a lake upload URL.
// In: binary Graph response. Out: an authenticated lake URL request.
if (msg.statusCode !== 200) {
  msg.proofFailureReason = 'SharePoint download HTTP ' + msg.statusCode;
  node.error(msg.proofFailureReason, msg);
  return null;
}

var bytes = msg.payload;
if (bytes && bytes.type === 'Buffer' && Array.isArray(bytes.data)) {
  bytes = Buffer.from(bytes.data);
}
if (!Buffer.isBuffer(bytes)) {
  msg.proofFailureReason = 'Graph response was not a binary Buffer';
  node.error(msg.proofFailureReason, msg);
  return null;
}
if (bytes.length !== msg.proofFile.size) {
  msg.proofFailureReason = 'Downloaded byte count does not match SharePoint';
  node.error(msg.proofFailureReason, msg);
  return null;
}

var folder = String(msg.proof.lakeFolder || '');
folder = folder.replace(/^\/+|\/+$/g, '');
var validPath = /^[A-Za-z0-9 .!*'()_/-]+$/;
var name = msg.proofFile.name;
if (!folder || folder.indexOf('..') !== -1 ||
  folder.indexOf('data/ten=') === 0 || !validPath.test(folder) ||
  !/^[A-Za-z0-9 .!*'()_-]+$/.test(name)) {
  msg.proofFailureReason = 'Invalid lake path or file name';
  node.error(msg.proofFailureReason, msg);
  return null;
}

msg.fileBytes = bytes;
msg.fileSize = bytes.length;
msg.lakePath = folder + '/' + name;
if (msg.lakePath.length > 1024) {
  msg.proofFailureReason = 'Lake path exceeds 1024 characters';
  node.error(msg.proofFailureReason, msg);
  return null;
}
msg.method = 'POST';
msg.url = msg.lakeBase + '/generateUploadObjectUrls';
msg.headers = {
  'Authorization': 'Bearer ' + msg.lakeToken,
  'Content-Type': 'application/json',
  'Accept': 'application/json'
};
msg.payload = {
  paths: [
    { path: msg.lakePath }
  ]
};
msg._proofStage = 'lake signed URL';
node.status({
  fill: 'blue',
  shape: 'dot',
  text: 'requesting lake upload URL'
});
return msg;

// Builds the unauthenticated PUT request for the signed lake URL.
// In: signed-URL response and file bytes. Out: a binary HTTP PUT request.
var body = msg.payload;
var signedUrl = body && body.objectUrls &&
  body.objectUrls[0] && body.objectUrls[0].signedUrl;
var bytes = msg.fileBytes;

if (bytes && bytes.type === 'Buffer' && Array.isArray(bytes.data)) {
  bytes = Buffer.from(bytes.data);
}

if (msg.statusCode !== 201 || !signedUrl) {
  msg.proofFailureReason = 'Lake signed URL HTTP ' + msg.statusCode;
  node.error(msg.proofFailureReason, msg);
  return null;
}
if (!Buffer.isBuffer(bytes)) {
  msg.proofFailureReason = 'Downloaded bytes are not a binary Buffer';
  node.error(msg.proofFailureReason, msg);
  return null;
}

msg.signedUrl = signedUrl;
msg.method = 'PUT';
msg.url = signedUrl;
msg.headers = {};
msg.payload = bytes;
delete msg.fileBytes;
msg._proofStage = 'lake file upload';
node.status({ fill: 'blue', shape: 'dot', text: 'uploading one file' });
return msg;

// Reports a successful lake upload without exposing tokens or signed URLs.
// In: signed PUT response. Out: a short debug message.
if (msg.statusCode !== 200) {
  msg.proofFailureReason = 'Lake PUT HTTP ' + msg.statusCode;
  node.error(msg.proofFailureReason, msg);
  return null;
}

var name = msg.proofFile.name;
var text = 'UPLOADED ' + name + ' (' + msg.fileSize + ' bytes) to ';
text += msg.lakePath;
if (msg.proofPartialList) {
  text += ' [first page only]';
}
msg.payload = text;
delete msg.proof;
delete msg.lakeToken;
delete msg.signedUrl;
delete msg.url;
delete msg.headers;
delete msg.method;
delete msg.fileBytes;
delete msg._proofStage;
node.status({ fill: 'green', shape: 'dot', text: 'lake upload complete' });
return msg;

// Reports a sanitized proof failure.
// In: a caught error. Out: a short debug message without request details.
var stage = msg._proofStage || 'proof';
var reason = msg.proofFailureReason || 'request failed';
var name = msg.proofFile && msg.proofFile.name;
var text = 'FAILED ' + stage;

if (name) {
  text += ' ' + name;
}
text += ': ' + reason;
msg.payload = text;
delete msg.proof;
delete msg.lakeToken;
delete msg.signedUrl;
delete msg.url;
delete msg.headers;
delete msg.method;
delete msg.fileBytes;
delete msg._proofStage;
delete msg.proofFailureReason;
node.status({ fill: 'red', shape: 'ring', text: 'proof failed' });
return msg;
